{
	"name": "@rizal72/oc-ponytail-widget",
	"version": "0.2.2",
	"type": "module",
	"description": "Unofficial ponytail level for OpenCode v2: the level in the prompt footer, next to the coffee cup, and a pill on the desktop that sets it",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/rizal72/opencode-plugins.git"
	},
	"license": "MIT",
	"files": [
		"*.ts",
		"!*.test.ts",
		"tui.js",
		"README.md",
		"dist"
	],
	"keywords": [
		"opencode",
		"opencode-plugin",
		"ponytail",
		"widget"
	],
	"publishConfig": {
		"access": "public"
	},
	"exports": {
		".": "./index.ts",
		"./tui": "./tui.js",
		"./rpc": "./rpc.ts",
		"./gui-experimental": "./dist/gui-experimental.cjs"
	}
}
